UPDATE questions SET topic = 'Games & Tournaments', prompt = 'How many games were played with a bet of ₹2?', passage = 'Pulak, Qasim, Ritesh, and Suresh participated in a tournament comprising of eight rounds. In each round, they formed two pairs, with each of them being in exactly one pair. The only restriction in the pairing was that the pairs would change in successive rounds. For example, if Pulak formed a pair with Qasim in the first round, then he would have to form a pair with Ritesh or Suresh in the second round. He would be free to pair with Qasim again in the third round. In each round, each pair decided whether to play the game in that round or not. If they decided not to play, then no money was exchanged between them. If they decided to play, they had to bet either ₹1 or ₹2 in that round. For example, if they chose to bet ₹2, then the player winning the game got ₹2 from the one losing the game. At the beginning of the tournament, the players had ₹10 each. The following table shows partial information about the amounts that the players had at the end of each of the eightrounds. It shows every time a player had ₹10 at the end of a round, as well as every time, at the end of a round, a player had either the minimum or the maximum amount that he would have had across the eight rounds. For example, Suresh had ₹10 at the end of Rounds 1, 3 and 8 and not after any of the other rounds. The maximum amount that he had at the end of any round was ₹13 (at the end of Round 5), and the minimum amount he had at the end of any round was ₹8 (at the end of Round 2). At the end of all other rounds, he must have had either ₹9, ₹11, or ₹12. It was also known that Pulak and Qasim had the same amount of money with them at the end of Round 4.', options = NULL, explanation = 'Official CAT 2022 Slot 3, DILR Q19. Answer key cross-checked against https://online.2iim.com/CAT-question-paper/CAT-2022-Question-Paper-Slot-3-DILR/', has_figure = FALSE WHERE id = 'cat-2022-s3-dilr-q19';
UPDATE questions SET answer = '6' WHERE id = 'cat-2022-s3-dilr-q19' AND NOT EXISTS (SELECT 1 FROM answer_key_corrections c WHERE c.question_id = 'cat-2022-s3-dilr-q19');
UPDATE questions SET topic = 'Games & Tournaments', prompt = 'Which of the following pairings was made in Round 5?', passage = 'Pulak, Qasim, Ritesh, and Suresh participated in a tournament comprising of eight rounds. In each round, they formed two pairs, with each of them being in exactly one pair. The only restriction in the pairing was that the pairs would change in successive rounds. For example, if Pulak formed a pair with Qasim in the first round, then he would have to form a pair with Ritesh or Suresh in the second round. He would be free to pair with Qasim again in the third round. In each round, each pair decided whether to play the game in that round or not. If they decided not to play, then no money was exchanged between them. If they decided to play, they had to bet either ₹1 or ₹2 in that round. For example, if they chose to bet ₹2, then the player winning the game got ₹2 from the one losing the game. At the beginning of the tournament, the players had ₹10 each. The following table shows partial information about the amounts that the players had at the end of each of the eightrounds. It shows every time a player had ₹10 at the end of a round, as well as every time, at the end of a round, a player had either the minimum or the maximum amount that he would have had across the eight rounds. For example, Suresh had ₹10 at the end of Rounds 1, 3 and 8 and not after any of the other rounds. The maximum amount that he had at the end of any round was ₹13 (at the end of Round 5), and the minimum amount he had at the end of any round was ₹8 (at the end of Round 2). At the end of all other rounds, he must have had either ₹9, ₹11, or ₹12. It was also known that Pulak and Qasim had the same amount of money with them at the end of Round 4.', options = '["Qasim and Suresh", "Pulak and Ritesh", "Pulak and Qasim", "Pulak and Suresh"]'::jsonb, explanation = 'Official CAT 2022 Slot 3, DILR Q20. Answer key cross-checked against https://online.2iim.com/CAT-question-paper/CAT-2022-Question-Paper-Slot-3-DILR/', has_figure = FALSE WHERE id = 'cat-2022-s3-dilr-q20';
